import { gs, GlideRecord } from '@servicenow/glide';
export function validateClosureChecklist(current, previous) {
    var newStatus = current.getValue('status');
    if (newStatus !== 'ready')
        return;
    var pending = [];
    if (current.getValue('attendance_cleared') !== 'true' && current.getValue('attendance_cleared') !== true) {
        pending.push('Attendance records not cleared');
    }
    if (current.getValue('expenses_cleared') !== 'true' && current.getValue('expenses_cleared') !== true) {
        pending.push('Expense records not cleared');
    }
    if (current.getValue('impact_cleared') !== 'true' && current.getValue('impact_cleared') !== true) {
        pending.push('Impact reports not cleared');
    }
    if (pending.length > 0) {
        current.setValue('pending_items', pending.join('; '));
        gs.addErrorMessage('Cannot mark as ready. Pending items: ' + pending.join(', '));
        current.setAbortAction(true);
    }
}
export function autoCheckClosureItems(current, previous) {
    var eventId = current.getValue('event');
    if (!eventId)
        return;
    // Check attendance: all should be completed, no_show, or corrected
    var pendingAtt = new GlideRecord('x_2248447_csr_ma_2_attendance');
    pendingAtt.addQuery('event', eventId);
    pendingAtt.addQuery('status', 'NOT IN', 'completed,no_show,corrected');
    pendingAtt.query();
    current.setValue('attendance_cleared', !pendingAtt.hasNext());
    // Check expenses: all should be reconciled or rejected
    var pendingExp = new GlideRecord('x_2248447_csr_ma_2_expense');
    pendingExp.addQuery('event', eventId);
    pendingExp.addQuery('status', 'NOT IN', 'reconciled,rejected');
    pendingExp.query();
    current.setValue('expenses_cleared', !pendingExp.hasNext());
    // Check impact: all should be verified or rejected
    var pendingImp = new GlideRecord('x_2248447_csr_ma_2_impact');
    pendingImp.addQuery('event', eventId);
    pendingImp.addQuery('status', 'NOT IN', 'verified,rejected');
    pendingImp.query();
    current.setValue('impact_cleared', !pendingImp.hasNext());
}
